-- 0011_playbook.sql
-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

create table public.lessons (
  id              int primary key references public.principles (id),
  chapter         text not null,   -- the page chapter this lesson closes
  stage           text not null check (stage in ('pre-launch', 'launch', 'early-revenue', 'scale', 'always')),
  title           text not null,
  move            text not null,
  evidence_query  text references public.case_queries (id),
  evidence        text not null,
  mechanism       text not null,
  steps           text not null,   -- one step per line
  metric          text not null,
  dont_copy_if    text not null
);

create table public.diagnostic_questions (
  n         int primary key,
  question  text not null,
  why       text not null,
  lesson_id int not null references public.lessons (id)   -- answered no: read this lesson's dont_copy_if first
);

create table public.diagnostic_bands (
  min_score int primary key,
  max_score int not null,
  verdict   text not null,
  advice    text not null
);

create table public.stage_playbook (
  sort     int primary key,
  stage    text not null,
  period   text not null,
  supabase text not null,
  you      text not null,
  lessons  text not null   -- lesson ids, comma separated
);

create table public.dont_copy (
  n     int primary key,
  title text not null,
  body  text not null
);

create table public.templates (
  id        text primary key,
  lesson_id int references public.lessons (id),
  title     text not null,
  takes     text not null,
  body_md   text not null
);
alter table public.lessons enable row level security;
create policy "Public read" on public.lessons for select to anon, authenticated using (true);
alter table public.diagnostic_questions enable row level security;
create policy "Public read" on public.diagnostic_questions for select to anon, authenticated using (true);
alter table public.diagnostic_bands enable row level security;
create policy "Public read" on public.diagnostic_bands for select to anon, authenticated using (true);
alter table public.stage_playbook enable row level security;
create policy "Public read" on public.stage_playbook for select to anon, authenticated using (true);
alter table public.dont_copy enable row level security;
create policy "Public read" on public.dont_copy for select to anon, authenticated using (true);
alter table public.templates enable row level security;
create policy "Public read" on public.templates for select to anon, authenticated using (true);

insert into public.case_queries (id, chapter, sort, sql, columns, footer_right, chart) values
  ('launch_week_fade', 'launch_weeks', 0, 'select extract(year from started)::int as year, count(*) as weeks, round(avg(lift), 1) as avg_lift,
       extract(year from started)::int = 2021 as _hot
from launch_week_star_lift group by 1, 4 order by 1;', '[{"name": "year", "type": "int4", "format": "mono"}, {"name": "weeks", "type": "int8", "format": "mono"}, {"name": "avg_lift", "type": "numeric", "format": "multiplier", "key": true}]'::jsonb, 'Same data, grouped by year. Source: OSS Insight (GH Archive)', '{"bar": "avg_lift", "max": 5}'::jsonb),
  ('lessons_index', 'principles', 0, 'select id, title, stage, metric from lessons order by id;', '[{"name": "id", "type": "int4", "format": "mono"}, {"name": "title", "type": "text", "format": "bold"}, {"name": "stage", "type": "text", "format": "mono"}, {"name": "metric", "type": "text"}]'::jsonb, null, null),
  ('stage_playbook', 'stages', 1, 'select stage, period, you, lessons from stage_playbook order by sort;', '[{"name": "stage", "type": "text", "format": "bold"}, {"name": "period", "type": "text", "format": "mono"}, {"name": "you", "type": "text"}, {"name": "lessons", "type": "text", "format": "mono"}]'::jsonb, null, null);

insert into public.lessons (id, chapter, stage, title, move, evidence_query, evidence, mechanism, steps, metric, dont_copy_if) values
  (1, 'taglines', 'pre-launch', 'Test positioning like a feature', 'Supabase changed one line of homepage copy two days before the Show HN, from "realtime postgres." to "The opensource Firebase alternative." Same product.', 'taglines_history', '8 databases in the weeks under the old line, 800 in the three days after the new one. Firebase stayed in the page title for five years.', 'The first line was a feature attached to a technology. The second named a tool the reader already used and a reason to switch. Four words moved it from feature differentiation to a specific segment: people who like Firebase but fear lock-in.', 'Write three one-line positionings: a feature line, a category line ("the open source X alternative") and a problem line.
Put each in front of 10 developers who match your ideal customer. Ask only: "What do you think this does, and who''s it for?" Count correct answers.
Ship the winner to your homepage for two weeks, then the runner-up for two weeks. Compare signups per unique visitor.
Keep the losing lines in a file. Positioning is a backlog, not a decision.', 'Signup rate per unique visitor (homepage to account created).', 'You change the line every week. Supabase kept one line for years once it worked. Testing is for finding the line, not for avoiding commitment.'),
  (2, 'taglines', 'pre-launch', 'Borrow a category before you build one', '"Firebase alternative" borrowed a category developers already understood instead of inventing one.', 'taglines_history', 'Five years later, Claude still names Supabase first in about 80% of "Firebase alternative" answers (our AI study).', 'A new category costs you a paragraph of education per reader. A borrowed one costs two words. Early on, clarity beats differentiation: nobody can prefer what they can''t classify.', 'Finish the sentence "We''re the ____ alternative" with a tool your ideal customers know. If none fits, try "____ for ____": an incumbent plus a segment it ignores.
Add one reason to switch that hits the incumbent''s known weakness (Supabase: lock-in).
Build an honest "You vs Incumbent" page that admits where the incumbent wins. It earns trust and ranks for the exact search people type.
Plan your exit from the borrowed category. Supabase moved to "Build in a weekend. Scale to millions." in 2022 and "The Postgres Development Platform." in 2025.', 'Share of signups from comparison or "alternative" searches.', 'The incumbent is loved and has no obvious weakness. "Alternative" only pulls people who already want to leave.'),
  (3, 'postgres_bet', 'pre-launch', 'Own day zero', 'Get chosen when the project starts, then never give the project a reason to leave.', 'time_to_first_row', 'AWS RDS: 8.5 minutes to launch, connect and insert a row. Supabase''s 2020 target: under a minute. Today: 5 seconds.', 'Developers pick a backend once per project, in the first hour. Whoever wins that hour wins the customer for years. Supabase didn''t need to win the scale argument on day one, only to not lose it later, which is what the Postgres choice guaranteed.', 'Stopwatch audit: three people who have never used your product, screen recorded, from your homepage to the first moment of real value. Do the same for your top competitor.
Log every step: each click, form field, email verification, docs page and error. Mark each one remove, defer or keep.
Defer everything that isn''t needed for first value: credit card, team setup, SSO, onboarding surveys.
Set a target in seconds or minutes, put it on the wall, and re-run the stopwatch every month.', 'Median time to first value for new signups, and the share who reach it in their first session.', 'Your value genuinely needs integration work (a scanner on a real codebase, observability on production traffic). Then shrink time to first proof instead: a demo dataset, a sandbox, a sample repo.'),
  (4, 'postgres_bet', 'launch', 'Build on something you don''t own', 'Supabase bet on Postgres instead of building its own database, and made leaving easy: it''s just Postgres, take your data and go.', 'hn_split', 'Of the 61 Hacker News stories over 100 points that link to or name Supabase, 29 (almost half) never say Supabase in the headline. They''re about Postgres.', 'Nobody owns Postgres, so everyone improves it, and every hyperscaler has to offer a good one: Supabase gets a better engine every year for free. Portability lowers the fear of trying. Content about the standard reaches people who would never click a vendor post.', 'Name the open standard under or next to your product. If there isn''t one, name the open format your users'' data lives in.
Write the exit doc, "How to leave us", as clearly as your quickstart. Link it from pricing.
Plan 10 posts that teach the standard itself, with your product in the last paragraph or not at all.
Contribute upstream, visibly. One merged PR to the standard is worth ten posts about your product.', 'Share of content traffic from posts that don''t name your product, and the signups they drive.', 'Your moat is the proprietary format. Then portability is a giveaway: borrow trust another way (compliance, benchmarks, named customers).'),
  (5, 'launch_weeks', 'launch', 'Make shipping an event, while it still works', 'Batch a quarter''s releases into one named Launch Week, one launch a day.', 'launch_week_fade', 'Average star lift per launch week fell every year: 3.8x in 2021, then 2.0x, 1.5x, 1.2x, and 1.0x in 2025.', 'Five launches in five days gives the community a reason to look every morning and gives newsletter writers a story instead of a changelog line. Early on, attention is the scarce resource and the format concentrates it. At scale it stops acquiring and becomes a ritual for existing users.', 'Keep a running list of everything you ship. At quarter end, pick the five best. If you can''t find five, run a launch day.
One item per day: a post, a demo under 60 seconds, and docs live before the post goes out.
Pre-brief 10 friendly developers and 3 newsletter writers a week ahead.
Measure lift against your own baseline (the 28 days before). Change the format when lift drops below 1.5x twice running.', 'Signups per day during the week divided by the daily average of the prior 28 days.', 'You ship once a quarter anyway, or your launches are invisible to users. Five weak launches teach your audience to ignore you.'),
  (6, 'origins', 'launch', 'Mean it on open source', 'Permissive licenses, no telemetry tricks, maintainers of the tools they depend on on payroll.', 'origins_timeline', 'The Show HN on 27 May 2020 drove 522 stars in a day, still the repo''s best day. 111K+ stars now.', 'Developers trust code they can read and self-host. That trust is what lets a four-person company get adopted by teams that would never buy from a startup.', 'Decide what''s open by one rule: is the open part useful on its own? If it''s a crippled demo of the paid product, keep it closed. Developers will find out.
Charge for operations (hosting, scale, compliance, support), not for features ripped out of the core.
Make self-hosting documented and boring. Most people who can self-host won''t, and those who do become your loudest advocates.', 'Outside contributors per month, and self-host to cloud conversions.', 'Open source isn''t table stakes in your category. It''s a distribution and trust strategy, not a moral requirement, and it costs real support time.'),
  (7, 'sales_motion', 'early-revenue', 'Free until it''s real', 'A generous free tier, with pricing that starts when the app has users, not while the developer is exploring.', 'revenue', 'Roughly $0 for the first 18 months, about $1M ARR by the end of the first revenue year, about $7.5M the year after.', 'Developers explore with side projects. Charging during exploration kills adoption; charging at production captures value when the user has budget and a reason to pay.', 'Find your production signal: the usage pattern that means "this is real" (traffic, team size, uptime needs, data volume).
Put your first paid line just past it. Everything before it is free.
Make the bill predictable: caps, spend alerts, no surprise invoices. One surprise bill on Hacker News costs more than a year of upgrades.
List the free projects that cross the production signal and don''t upgrade. That''s your sales pipeline.', 'Free to paid conversion among projects past the production signal (not among all signups).', 'You can''t afford 18 months of free-tier infrastructure. Supabase could because an idle database cost it almost nothing. Do the maths before copying the generosity.'),
  (8, 'sales_motion', 'early-revenue', 'Sales as support', 'Reps reach out when usage says the customer needs help (limits, errors, spikes), not when a lead score says they might buy.', 'sales_cohorts', 'Product-led accounts left alone grew 25% quarter on quarter. Accounts that spoke to a rep grew 125%.', 'The message lands at the moment the developer has a problem, so it reads as help, not a pitch. Reps were measured on uplift against accounts nobody contacted, so they couldn''t claim growth that would have happened anyway.', 'Pick three triggers: near a plan limit, an error spike, usage doubling week on week.
When one fires, a founder sends a plain-text note: what you noticed, one specific suggestion, an offer to talk. No deck.
Hold back a random 20% of triggered accounts as a control group. Compare 90-day expansion.
Hire a rep only once the founder-run version beats the control. Pay them on that lift.', '90-day expansion of contacted accounts vs the control group.', 'Fewer than about 50 accounts hit a trigger each month. Then just talk to all of them: a control group that small tells you nothing.'),
  (9, 'ai_waves', 'scale', 'Be legible to AI', 'Supabase became the default backend for AI app builders and coding agents, which now create most of its new databases.', 'ai_waves', 'In our study, Claude names Supabase first in about 90% of generic "database plus login" answers, and in 0 of 124 control prompts.', 'Years of public Reddit threads, GitHub discussions and clear docs became training data. Then Supabase built for agents directly: a CLI and MCP server an agent can drive, and declarative schemas in Git.', 'Ask three AI models the question your ideal customer would ask, 10 times each. Count how often you''re named, and first. That''s your baseline (our prompts and scripts are open source).
Publish llms.txt and make docs readable as plain text, one concept per page.
Make the product drivable without a browser: a CLI with clear errors, an OpenAPI spec, an MCP server if agents would use it.
Answer questions in public (GitHub discussions, Stack Overflow, Reddit), not only in a Discord no model will ever read.
Re-run the baseline every quarter.', 'Share of AI answers that name you first, across your 10 most important prompts.', 'You think it''s a trick. Models recommend what the public internet already recommends. This is the teach-the-standard strategy with a new reader.'),
  (10, 'rounds', 'always', 'Stay frugal longer', 'Supabase raised a $6M seed and stayed small and remote. Copplestone''s rule: money doesn''t solve your problems.', 'rounds', 'A month of developer interviews before writing code (January 2020), and a team kept small through the first revenue years.', 'A small team keeps the founders close to users, which is where every other lesson came from.', 'Before every hire, write one sentence: "This is burning, and it will keep burning without this person." If you can''t, don''t hire.
Fix founder hours on user calls each week (start with five), however big you get.
Pick investors whose interest grows as you do.', 'Month-3 retention: of developers active in their first month, how many are still active in month 3?', 'A competitor is buying the category and the window is closing. Frugality is a default, not a religion.');

insert into public.diagnostic_questions (n, question, why, lesson_id) values
  (1, 'Is there an incumbent your buyer already knows by name?', '"X alternative" only works if X is famous.', 2),
  (2, 'Can a developer get value in under 10 minutes without talking to you?', 'Winning day zero needs self-serve.', 3),
  (3, 'Is your product built on an open standard you don''t own?', 'You can borrow its trust and offer portability.', 4),
  (4, 'Does usage grow on its own once a project succeeds?', 'Free-until-production pricing needs usage that compounds.', 7),
  (5, 'Do you ship something users notice at least monthly?', 'Launch weeks need a backlog worth batching.', 5),
  (6, 'Is your core genuinely useful as open source, or could it be?', 'Open source as a lead magnet gets punished.', 6),
  (7, 'Would an AI coding agent ever need to pick a tool in your category?', 'AI legibility is a channel, not a nice-to-have.', 9),
  (8, 'Does the developer make the decision, not procurement?', 'Bottom-up only works if the user holds the pen.', 8);

insert into public.diagnostic_bands (min_score, max_score, verdict, advice) values
  (6, 8, 'Supabase-shaped', 'Most lessons apply nearly as written. Start with your stage in the playbook below.'),
  (3, 5, 'Partly Supabase-shaped', 'Take the mechanisms, change the tactics. Read the "Don''t copy this if" line of every lesson you answered no to.'),
  (0, 2, 'Not Supabase-shaped', 'You''re probably sales-led or selling infrastructure to enterprises. Read lessons 1, 3, 8 and 10 and skip the rest.');

insert into public.stage_playbook (sort, stage, period, supabase, you, lessons) values
  (1, 'Pre-launch', 'Dec 2019 to May 2020', 'A month of developer interviews, then building. Tested the tagline before the Show HN.', 'Interview 20 developers before writing code. Run the tagline test. Run the stopwatch on the incumbent.', '1, 2, 3'),
  (2, 'Launch to first traction', 'May 2020 to 2021', 'Show HN #1, YC S20, $6M seed, first launch week.', 'One big launch moment built around the borrowed category. Teach the standard. Start a launch cadence.', '2, 4, 5, 6'),
  (3, 'Early revenue', '2021 to 2023', 'Free until production, usage-triggered sales, launch weeks at peak lift.', 'Find your production signal. Run founder-led triggered outreach with a control group.', '7, 8'),
  (4, 'Scale', '2023 onward', 'pgvector, AI app builders, coding agents. Launch weeks turn into retention.', 'Measure your AI visibility, build for agents, check which rituals still acquire users.', '5, 9'),
  (5, 'Always', 'Every stage', 'Small team, founders close to users.', 'Retention is the north star until it holds.', '10');

insert into public.dont_copy (n, title, body) values
  (1, 'The luck', 'Copplestone says it himself: if agents settle on two or three defaults per category, most tools won''t be one of them, and you can''t plan for that. Do the fundamentals; don''t build a plan that needs lightning to strike.'),
  (2, 'The insecure defaults', 'About 170 of 1,645 AI-built apps had tables open to the world because RLS was never switched on. Speed to value without safe defaults becomes someone else''s breach and your headline. Make the safe path the fast path.'),
  (3, 'Concentration risk', 'If one partner sends most of your users, your growth sits on their roadmap. App builders are now launching their own backends.'),
  (4, 'Free usage as revenue', 'Millions of free agent-created databases are a vanity number until a slice converts.'),
  (5, 'Launch weeks forever', 'Measure the lift, and change the format when it stops working. Supabase''s fell every year.');

insert into public.templates (id, lesson_id, title, takes, body_md) values
  ('tagline_test', 1, 'Tagline test', '1 week', '# Tagline test (1 week)

| Line | Type | 10 devs: described correctly | Signups per unique visitor (2 weeks live) |
| --- | --- | --- | --- |
| | Feature | /10 | |
| | Category ("X alternative") | /10 | |
| | Problem | /10 | |

Ask: "What do you think this does, and who''s it for?" Don''t explain. Don''t defend.
'),
  ('stopwatch_audit', 3, 'Stopwatch onboarding audit', 'Half a day', '# Stopwatch onboarding audit (half a day)

| Step | Seconds | Needed for first value? | Remove / defer / keep |
| --- | --- | --- | --- |
| Land on homepage | | | |
| Sign up | | | |
| ... | | | |
| **First value** | **total** | | |

Run it for your product and your top competitor. Same tester, same machine. Supabase''s benchmark: 8.5 minutes on AWS RDS, 5 seconds on Supabase.
'),
  ('launch_week', 5, 'Launch week planner', '1 quarter', '# Launch week planner

| Day | What ships | Post | Demo (60s) | Docs live | Who''s briefed |
| --- | --- | --- | --- | --- | --- |
| Mon | The biggest thing | | | | |
| Tue | | | | | |
| Wed | Something for the community (OSS, free) | | | | |
| Thu | | | | | |
| Fri | One more thing | | | | |

Baseline: signups per day for the prior 28 days = ____
Lift = average signups per day during the week / baseline. Change the format when lift drops below 1.5x twice running.
'),
  ('teach_the_standard', 4, 'Teach the standard: 10 posts', '1 quarter', '# Teach the standard: 10 posts

Ten posts about the open standard your product sits on, widest audience first:

1. The thing most people get wrong about [standard]
2. [Standard] vs [alternative]: an honest comparison
3. How [standard] actually works under the hood
4. 5 features of [standard] nobody uses
5. How we''d set up [standard] for a team of 5
6. Performance: what we measured
7. Security defaults you should change today
8. [Standard] in production: a user''s story (they''re the hero)
9. Where [standard] is going next
10. Why we built on [standard] (the only post about you)
'),
  ('triggered_outreach', 8, 'Usage-triggered outreach', 'Ongoing', '# Usage-triggered outreach

| Trigger | Threshold | Message (plain text, from a founder) | Control group |
| --- | --- | --- | --- |
| Near plan limit | 80% of limit | "Noticed you''re close to the X limit. Here''s how teams your size usually handle it..." | 20% random |
| Error spike | 3x baseline in 24h | "Saw a jump in Y errors on your project. Looks like Z; here''s the fix..." | 20% random |
| Usage doubling | 2x week on week | "Your usage doubled this week. Anything we can unblock?" | 20% random |

Report monthly: 90-day expansion, contacted vs control.
'),
  ('ai_legibility', 9, 'AI legibility checklist', '1 day, then quarterly', '# AI legibility checklist

- [ ] Baseline: 10 prompts your ideal customer would ask x 3 models x 10 runs. How often are you named first?
- [ ] llms.txt at your docs root
- [ ] Docs readable as plain text, one concept per page, code examples that run
- [ ] CLI with clear errors and non-interactive flags
- [ ] OpenAPI spec published
- [ ] MCP server (if agents would use your product)
- [ ] Support answers in public places, not only Discord
- [ ] Safe defaults when an agent sets you up with zero configuration
- [ ] Re-run the baseline quarterly
');

-- Keep the shared checklist in step with the lessons (same ids, so existing ticks carry over).
update public.principles set title = 'Test positioning like a feature', body = 'Supabase changed one line of homepage copy two days before the Show HN, from "realtime postgres." to "The opensource Firebase alternative." Same product.', how = 'Write three one-line positionings: a feature line, a category line ("the open source X alternative") and a problem line.' where id = 1;
update public.principles set title = 'Borrow a category before you build one', body = '"Firebase alternative" borrowed a category developers already understood instead of inventing one.', how = 'Finish the sentence "We''re the ____ alternative" with a tool your ideal customers know. If none fits, try "____ for ____": an incumbent plus a segment it ignores.' where id = 2;
update public.principles set title = 'Own day zero', body = 'Get chosen when the project starts, then never give the project a reason to leave.', how = 'Stopwatch audit: three people who have never used your product, screen recorded, from your homepage to the first moment of real value. Do the same for your top competitor.' where id = 3;
update public.principles set title = 'Build on something you don''t own', body = 'Supabase bet on Postgres instead of building its own database, and made leaving easy: it''s just Postgres, take your data and go.', how = 'Name the open standard under or next to your product. If there isn''t one, name the open format your users'' data lives in.' where id = 4;
update public.principles set title = 'Make shipping an event, while it still works', body = 'Batch a quarter''s releases into one named Launch Week, one launch a day.', how = 'Keep a running list of everything you ship. At quarter end, pick the five best. If you can''t find five, run a launch day.' where id = 5;
update public.principles set title = 'Mean it on open source', body = 'Permissive licenses, no telemetry tricks, maintainers of the tools they depend on on payroll.', how = 'Decide what''s open by one rule: is the open part useful on its own? If it''s a crippled demo of the paid product, keep it closed. Developers will find out.' where id = 6;
update public.principles set title = 'Free until it''s real', body = 'A generous free tier, with pricing that starts when the app has users, not while the developer is exploring.', how = 'Find your production signal: the usage pattern that means "this is real" (traffic, team size, uptime needs, data volume).' where id = 7;
update public.principles set title = 'Sales as support', body = 'Reps reach out when usage says the customer needs help (limits, errors, spikes), not when a lead score says they might buy.', how = 'Pick three triggers: near a plan limit, an error spike, usage doubling week on week.' where id = 8;
update public.principles set title = 'Be legible to AI', body = 'Supabase became the default backend for AI app builders and coding agents, which now create most of its new databases.', how = 'Ask three AI models the question your ideal customer would ask, 10 times each. Count how often you''re named, and first. That''s your baseline (our prompts and scripts are open source).' where id = 9;
update public.principles set title = 'Stay frugal longer', body = 'Supabase raised a $6M seed and stayed small and remote. Copplestone''s rule: money doesn''t solve your problems.', how = 'Before every hire, write one sentence: "This is burning, and it will keep burning without this person." If you can''t, don''t hire.' where id = 10;
